etc/amx/timingila/timingila.odl.text:
#!/usr/bin/amxrt

%config {
    // Application name
    name = "timingila";

    // amxo parser config-options
    import-dbg = false;

    // amxrt config-options
    auto-detect = true;
    auto-connect = true;
    //daemon = false;
    priority = 0;
    pid-file = true;

    // bus specific configuration
    pcb = {
        register-name = "${name}"
    };

    privileges = {
        capabilities = []
    };

    sahtrace = {
        type = "syslog",
        level = 500
    };

    trace-zones = {timingila_dm = 100,
                   softwaremodules_du = 100,
                   softwaremodules_ee = 100,
                   softwaremodules_eu = 100,
                   rlyeh = 100,
                   cthulhu = 100,
                   container_adapter = 100,
                   packager_adapter = 100,
                   dm-mngr-eu = 100,
                   dm-mngr-du = 100,
                   dm-mngr-ee = 100,
                   softwaremodules_helper = 100,
                   DMMNGR = 100,
                   DMMNGR_DU = 100,
                   uuid = 100,
                   rpc = 100 };


    // Application specific settings

    // persistent storage location
    rw_data_path = "/etc/config";
/// odl = {
///     load-dm-events = false,
///     dm-save = true,
///     dm-save-on-changed = true,
///     dm-save-delay = 1000,
///     directory = "${storage-path}/odl"
/// };

    ubus = {
        watch-ubus-events = true
    };

    // main files
    definition_file = "${name}_definition.odl";
    definition_softwaremodules_file = "softwaremodules_definition.odl";
    save_file = "${rw_data_path}/${name}/${name}.odl";
    defaults_file = "${name}_defaults.odl";
    defaults_softwaremodules_file = "softwaremodules_defaults.odl";
}

import "${name}.so" as "${name}";
import "mod-dmproxy.so" as proxy;

#include "mod_sahtrace.odl";

include "${definition_softwaremodules_file}";
include "${definition_file}";

?include "${save_file}":"${defaults_softwaremodules_file}";
?include "${save_file}":"${defaults_file}";


%define {
    entry-point proxy.dm_proxy_main;
    entry-point timingila.timingila_main;
}

etc/amx/timingila/timingila_definition.o.text:
%define {
	object Timingila {
		%read-only string version = "alpha";

		/***
		 * Load a packager plugin
		 * %param string full path of the plugin
		 */
		bool loadPluginPackager(%in %mandatory %strict string plugin);

		/***
		 * Load a container plugin
		 * %param string full path of the plugin
		 */
		bool loadPluginContainer(%in %mandatory %strict string plugin);

		%read-only string PackagerPluginPath = "";
		%read-only string ContainerPluginPath = "";

		bool rmAfterUninstall(%in %mandatory bool enable);

		%read-only bool RmAfterUninstall = true;

		bool lateInit();

		object ProxyManager {
			%private bool register(%in %mandatory string proxy, %in %mandatory string real);
			%private bool unregister(%in %mandatory string proxy);
			htable 'list'();
		}
	}
}

etc/amx/timingila/softwaremodules_defini.text:
%define {
	object SoftwareModules {
		event "DUStateChange!";

		/***
		 * Install one or more Deployment Units (DUs) to the associated SoftwareModules.
		 */
		%async bool InstallDU(%in %mandatory %strict string URL,
					   %in %mandatory %strict string UUID,
					   %in %strict string Username,
					   %in %strict string Password,
					   %in %mandatory %strict string ExecutionEnvRef,
					   %in int32 AllocatedMemory,
					   %in int32 AllocatedDiskSpace,
					   %in int32 AllocatedCPUPercent,
					   %in bool AutoStart,
					   %in list HostObject,
					   %in list NetworkConfig,
					   %in %strict htable Data,
					   %in %strict string Signature,
                                           %in string ModuleVersion);

		/***
		 * Add one Execution Environment
		 */
		%async bool AddExecEnv(%in %mandatory %strict string Name,
						%in %mandatory %strict string Vendor,
						%in %mandatory %strict string Version,
						%in %mandatory %strict string ParentExecEnv,
						%in %mandatory int16 InitialRunLevel,
						%in %mandatory int32 AllocatedMemory,
						%in %mandatory int32 AllocatedDiskSpace,
						%in %mandatory int32 AllocatedCPUPercent,
						%in int32 MaxBandwidthUpstream,
						%in int32 MaxBandwidthDownstream);


		/***
		 * https://usp-data-models.broadband-forum.org/tr-181-2-14-0-usp.html#D.Device:2.Device.SoftwareModules.ExecEnv.{i}.
		 *
		 */
		object ExecEnv[] {
			counted with ExecEnvNumberOfEntries;

			bool Enable;
			%read-only string Status {
				default "Disabled";
				on action validate call check_enum [ "Up", "Error", "Restarting", "Disabled" ];
			}
			%unique %key string Alias {
				on action validate call check_maximum_length 64;
			}
			%unique %key string Name {
				on action validate call check_maximum_length 32;
			}
			%read-only string Type {
				on action validate call check_maximum_length 64;
			}
			int16 InitialRunLevel {
				default -1;
				on action validate call check_range { min = -1, max = 65535 };
			}
			%read-only int16 CurrentRunLevel {
				default -1;
				on action validate call check_range { min = -1, max = 65535 };
			}
			int16 InitialExecutionUnitRunLevel{
				default -1;
				on action validate call check_range { min = -1, max = 65535 };
			}
			%read-only string Vendor {
				on action validate call check_maximum_length 128;
			}
			%read-only string Version {
				on action validate call check_maximum_length 32;
			}
			%read-only int32 AllocatedDiskSpace {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
			}
			%read-only int32 AvailableDiskSpace {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call ee_read_stats;
			}
			%read-only int32 AllocatedMemory {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
			}
			%read-only int32 AvailableMemory {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call ee_read_stats;

			}
			%read-only int32 AllocatedCPUPercent {
				default -1;
				on action validate call check_range { min = -1, max = 100 };
			}
			%read-only csv_string ActiveExecutionUnits{
				default "";
			}
			%read-only csv_string ProcessorRefList{
				default "";
			}
			%read-only string ParentExecEnv {
				default "";
			}
			%read-only string RestartReason {
				default "";
				on action validate call check_maximum_length 256;
			}
			string Description {
				default "";
				on action validate call check_maximum_length 256;
				on action write call ee_write_description;
			}
			%read-only datetime CreatedAt;

			bool SetRunLevel(%in %strict int32 RequestedRunLevel);
			bool Restart(%in %strict string RestartReason);

			/***
			* Modify the constraints of the EE. The changes will be applied after a Restart of the EE.
			*/
			bool ModifyConstraints(%in bool Force, %in int64 AllocatedDiskSpace, %in int64 AllocatedMemory, %in int32 AllocatedCPUPercent);

			/***
			* Delete the execution environment
			*/
			bool Delete();
		}

		/***
		 * https://usp-data-models.broadband-forum.org/tr-181-2-14-0-usp.html#D.Device:2.Device.SoftwareModules.DeploymentUnit.{i}.
		 *
		 */
		object DeploymentUnit[] {
			counted with DeploymentUnitNumberOfEntries;

			%key string UUID {
			/**
				on action validate call check_maximum_length 36;
			*/
			}
			%read-only string DUID {
				default "000000000000000000000000000000000000";
				on action validate call check_maximum_length 36;
			}
			%unique %key string Alias {
				on action validate call check_maximum_length 64;
			}
			%read-only string Name {
				on action validate call check_maximum_length 64;
			}
			%read-only string Status {
				default "Installing";
				on action validate call check_enum [ "Installing", "Installed", "Updating", "Uninstalling", "Uninstalled", "Failed" ];
			}
			%read-only bool Resolved {
				default true;
			}
			%read-only string URL {
				on action validate call check_maximum_length 2048;
			}
			%read-only string Description {
				default "";
				on action validate call check_maximum_length 256;
			}
			%read-only string Vendor {
				on action validate call check_maximum_length 128;
			}
			%read-only string Version {
				on action validate call check_maximum_length 32;
			}
			%read-only csv_string VendorLogList {
				default "";
			}
			%read-only csv_string VendorConfigList{
				default "";
			}
			%read-only csv_string ExecutionUnitList{
				default "";
			}
			%read-only datetime Installed;
			%read-only datetime LastUpdate;
			%key string ExecutionEnvRef;
                        %read-only string ModuleVersion {
                                on action validate call check_maximum_length 32;
                        }


			%async bool Update(%in %strict string URL,
			 			%in %strict string Username,
						%in %strict string Password,
						%in bool RetainData,
						%in int32 AllocatedMemory,
						%in int32 AllocatedDiskSpace,
						%in int32 AllocatedCPUPercent,
						%in list HostObject,
						%in list NetworkConfig,
                                                %in string ModuleVersion,
						%in %strict htable Data);

			%async bool Uninstall(%in bool RetainData);
		}

		/***
		 *
		 *
		 */
		object ExecutionUnit[] {
			counted with ExecutionUnitNumberOfEntries;

			%key string EUID {
			/**
				on action validate call check_maximum_length 64;
			*/
			}
			%unique %key string Alias {
				on action validate call check_maximum_length 64;
			}
			%read-only string Name {
				on action validate call check_maximum_length 32;
			}
			%read-only string ExecEnvLabel {
				on action validate call check_maximum_length 64;
			}
			%read-only string Status {
                default "Idle";
                on action validate call check_enum [ "Idle",
                    "Starting", "Active", "Stopping", "Restarting"];
            }
			%read-only string ExecutionFaultCode {
				default "NoFault";
				on action validate call check_enum [ "NoFault", "FailureOnStart", "FailureOnAutoStart", "FailureOnStop", "FailureWhileActive", "DependencyFailure", "UnStartable" ];
			}
			%read-only string ExecutionFaultMessage {
				on action validate call check_maximum_length 256;
			}
			bool AutoStart;

			uint16 RunLevel;
			%read-only string Vendor {
				on action validate call check_maximum_length 128;
			}
			%read-only string Version {
				on action validate call check_maximum_length 32;
			}
			%read-only string Description {
				on action validate call check_maximum_length 256;
			}

			%read-only int32 AllocatedDiskSpace {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call eu_read_stats;
			}
			%read-only int32 AllocatedMemory {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call eu_read_stats;
			}
			%read-only int32 AllocatedCPUPercent {
				default -1;
				on action validate call check_range { min = -1, max = 100 };
				on action read call eu_read_stats;
			}

			%read-only int32 AvailableDiskSpace {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call eu_read_stats;
			}
			%read-only int32 AvailableMemory {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call eu_read_stats;
			}

			%read-only int32 DiskSpaceInUse {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call eu_read_stats;
			}
			%read-only int32 MemoryInUse {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call eu_read_stats;
			}

			%read-only csv_string References;
			%read-only csv_string AssociatedProcessList;
			%read-only csv_string VendorLogList;
			%read-only csv_string VendorConfigList;
			%read-only string ExecutionEnvRef;

			%read-only object NetworkConfig {
				%read-only object AccessInterfaces[] {
					%read-only string Reference;
				}
				%read-only object PortForwarding[] {
					%read-only string Interface;
					%read-only uint32 ExternalPort;
					%read-only uint32 InternalPort;
					%read-only string Protocol;
				}
			}

			%read-only object HostObject[] {
				%unique %key string Alias {
					on action validate call check_maximum_length 64;
				}
				%read-only string Source {
					on action validate call check_maximum_length 256;
				}
				%read-only string Destination {
					on action validate call check_maximum_length 256;
				}
				%read-only string Options {
					on action validate call check_maximum_length 256;
				}
			}

			bool SetRequestedState(%in %strict string RequestedState);
			bool ModifyNetworkConfig(%in list NetworkConfig);
			object Extensions {
				// To Define
			}
		}

		%read-only object NetworkConfig {
			%read-only object Interfaces[] {
				/** The logical name of the interface */
				%read-only string Name;
				/** A reference to a Device.Logical.Interfaces.{i}. row */
				%read-only string Reference;
			}
			/** the bridge to which the containers will connect */
			%read-only string DefaultBridge;
			/** row in Firewall.Chain. to which the firewall rules should be applied */
			%read-only string DefaultFirewallChain;
		}
	}
}

%populate {
    on event "dm:object-changed" call eu_change_autostart
		filter 'path matches "^SoftwareModules\.ExecutionUnit\.[0-9]+\.$" && contains("parameters.AutoStart")';

	on event "dm:object-changed" call ee_change_enable
		filter 'path matches "^SoftwareModules\.ExecEnv\.[0-9]+\.$" && contains("parameters.Enable")';
}

etc/amx/rlyeh/rlyeh.odl.text:
#!/usr/bin/amxrt

%config {
    // Application name
    name = "rlyeh";

    // amxo parser config-options
    import-dbg = false;

    // amxrt config-options
    auto-detect = true;
    auto-connect = true;
    //daemon = false;
    priority = 0;
    pid-file = true;

    // bus specific configuration
    pcb = {
        register-name = "${name}"
    };

    privileges = {
        capabilities = []
    };

    sahtrace = {
        type = "file",
        file = "/logs/rlyeh.log",
        level = 500
    };

    trace-zones = ["rlyeh_events", "rlyeh_notif", "rlyeh_signature",
                   "rlyeh_functions", "rlyeh_copy", "rlyeh_utils", "rlyeh_remove"];

    // Application specific settings
    // persistent storage location
    rw_data_path = "${prefix}/etc/config";

    // main files
    definition_file = "${name}_definition.odl";
    save_file = "${rw_data_path}/${name}/${name}.odl";
    defaults_file = "${name}_defaults.odl";
}

import "${name}.so" as "${name}";

include "${definition_file}";
?include "${save_file}":"${defaults_file}";
#include "mod_sahtrace.odl";

%define {
    entry-point rlyeh.rlyeh_main;
}

etc/amx/rlyeh/rlyeh_defaults.odl.text:
%populate {
    object Rlyeh {
        parameter OnboardingFile = "/opt/lcm/usr/share/rlyeh_onboarded";
        parameter ImageLocation = "/opt/lcm/usr/share/rlyeh/images";
        parameter ROImageLocation = "/usr/rlyeh/images";
        parameter StorageLocation = "/opt/lcm/usr/share/rlyeh/blobs";
        parameter ROStorageLocation = "/usr/rlyeh/blobs";
        parameter SignatureVerification = 0;
        parameter CertificateVerification = 0;
        parameter RemainingDiskSpaceBytes = 1000001;
    }
}

etc/amx/rlyeh/rlyeh_definition.odl.text:
%define {
    object Rlyeh {

        event "rlyeh:image:list";
        event "rlyeh:image:status";
        event "rlyeh:image:pulled";
        event "rlyeh:image:markedremove";
        event "rlyeh:image:removed";
        event "rlyeh:error";

        /*
         * File created after onboarding sequence has executed
         * Should only be executed once
         */
        %read-only string OnboardingFile;
        %read-only string ImageLocation;
        %read-only string ROImageLocation;
        %read-only string StorageLocation;
        %read-only string ROStorageLocation;
        %read-only bool SignatureVerification;
        %read-only bool CertificateVerification;
        %read-only int64 RemainingDiskSpaceBytes;

        void command(%in %mandatory string command,
                     %in string commandID,
                     %in htable parameters);

        /*
         * pull in docker/oci images using librlyeh
         */
        void pull(%in %mandatory string URI, %in %mandatory string DUID, %in string username, %in string password, %in string signature);

        /*
         * mark image for removal
         */
        void remove(%in string DUID, %in string Version);

        /*
         * garbage collection: remove all images that were previously marked for removal
         */
        void gc();

        /*
         * Enable/Disable signature verification (sv)
         */
        void sv(%in bool Enable);

        void "list"(%in string image-filter);
        void status(%in string DUID, %in string Version);

        %persistent object Images [] {
            %persistent %key string DUID;
            %persistent string Name;
            %persistent string DiskLocation;
            %persistent string URI;
            %persistent %key string Version;
            %persistent string Vendor;
            %persistent string Description;
            %persistent bool MarkForRemoval;
            %persistent string Status;
            %persistent uint32 ErrorCode;
        }
    }
}

%populate {
/*
    on event "dm:instance-added" call image_pulled
        filter 'path == "Rlyeh.Images."';

    on event "*" call print_event;
*/
}

etc/amx/cthulhu/cthulhu.odl.text:
#!/usr/bin/amxrt

%config {
    // Application name
    name = "cthulhu";

    // amxo parser config-options
    import-dbg = false;

    // amxrt config-options
    auto-detect = true;
    auto-connect = true;
    //daemon = false;
    priority = 0;
    pid-file = true;

    // bus specific configuration
    pcb = {
        register-name = "${name}"
    };

    privileges = {
        keep-all = true
    };

    sahtrace = {
        type = "file",
	    file = "/logs/cthulhu.log",
        level = 500
    };

    trace-zones = {cthulhu_main = 500,
                   cthulhu_dm = 500,
                   cthulhu_events = 500,
                   cthulhu_lxc = 500,
                   cthulhu_archive = 500,
                   cthulhu_autorestart = 500,
                   cthulhu_sb = 500,
                   cthulhu_ns = 500,
                   cthulhu_helpers = 500,
                   cthulhu_ovl = 500,
                   cthulhu_storage = 500,
                   cthulhu_cgroup = 500,
                   cthulhu_rpc = 500,
                   cthulhu_syslogng = 500,
                   cthulhu_annotations = 500,
                   cthulhu_plugins = 500,
                   cthulhu_onboard = 500,
                   rpc = 500,
                   plugin = 500};

    // Application specific settings

    // persistent storage location
    // rw_data_path = "/etc/config";
    storage-path = "${rw_data_path}/${name}/";

    // main files
    definition_file = "${name}_definition.odl";
    config_file = "${name}_config.odl";

    odl = {
        load-dm-events = true,
        dm-load = true,
        dm-defaults = "defaults.d/",
        dm-save = true,
        dm-save-on-changed = true,
        dm-save-delay = 1000,
        directory = "${storage-path}/odl"
    };
}

import "${name}.so" as "${name}";

include "${definition_file}";
include "${config_file}";

#include "mod_sahtrace.odl";

%define {
    entry-point cthulhu.cthulhu_main;
}

etc/amx/cthulhu/cthulhu_config.odl.text:
