etc/amx/timingila/softwaremodules_defini.text:
%define {
	object SoftwareModules {
		event "DUStateChange!";

		/***
		 * Install one or more Deployment Units (DUs) to the associated SoftwareModules.
		 */
		%async bool InstallDU(%in %mandatory %strict string URL,
					   %in %mandatory %strict string UUID,
					   %in %strict string Username,
					   %in %strict string Password,
					   %in %mandatory %strict string ExecutionEnvRef,
					   %in int32 AllocatedMemory,
					   %in int32 AllocatedDiskSpace,
					   %in int32 AllocatedCPUPercent,
					   %in bool AutoStart,
					   %in list HostObject,
					   %in list NetworkConfig,
					   %in %strict htable Data,
					   %in list EnvVariable,
					   %in %strict string Signature,
					   %in string ModuleVersion,
					   %in csv_string RequiredRoles,
					   %in csv_string OptionalRoles);

		/***
		 * Add one Execution Environment
		 */
		%async bool AddExecEnv(%in %mandatory %strict string Name,
						%in %mandatory %strict string Vendor,
						%in %mandatory %strict string Version,
						%in %mandatory %strict string ParentExecEnv,
						%in %mandatory uint32 InitialRunLevel,
						%in %mandatory int32 AllocatedMemory,
						%in %mandatory int32 AllocatedDiskSpace,
						%in %mandatory int32 AllocatedCPUPercent,
						%in int32 MaxBandwidthUpstream,
						%in int32 MaxBandwidthDownstream,
						%in csv_string AvailableRoles);


		/***
		 * https://usp-data-models.broadband-forum.org/tr-181-2-14-0-usp.html#D.Device:2.Device.SoftwareModules.ExecEnv.{i}.
		 *
		 */
		%read-only object ExecEnv[] {
			counted with ExecEnvNumberOfEntries;

			bool Enable;
			%read-only string Status {
				default "Disabled";
				on action validate call check_enum [ "Up", "Error", "Restarting", "Disabled" ];
			}
			%unique %key string Alias {
				on action validate call check_maximum_length 64;
			}
			%unique %key string Name {
				on action validate call check_maximum_length 32;
			}
			%read-only string Type {
				on action validate call check_maximum_length 64;
			}
			uint32 InitialRunLevel {
				on action validate call check_range { min = 0, max = 65535 };
			}
			%read-only int32 CurrentRunLevel {
				default -1;
				on action validate call check_range { min = -1, max = 65535 };
			}
			int32 InitialExecutionUnitRunLevel{
				default -1;
				on action validate call check_range { min = -1, max = 65535 };
			}
			%read-only string Vendor {
				on action validate call check_maximum_length 128;
			}
			%read-only string Version {
				on action validate call check_maximum_length 32;
			}
			%read-only int32 AllocatedDiskSpace {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
			}
			%read-only int32 AvailableDiskSpace {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call ee_read_stats;
			}
			%read-only int32 AllocatedMemory {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
			}
			%read-only int32 AvailableMemory {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call ee_read_stats;

			}
			%read-only int32 AllocatedCPUPercent {
				default -1;
				on action validate call check_range { min = -1, max = 100 };
			}
			%read-only csv_string ActiveExecutionUnits{
				default "";
			}
			%read-only csv_string ProcessorRefList{
				default "";
			}
			%read-only string ParentExecEnv {
				default "";
			}
			%read-only string RestartReason {
				default "";
				on action validate call check_maximum_length 256;
			}
			string Description {
				default "";
				on action validate call check_maximum_length 256;
				on action write call ee_write_description;
			}
			%read-only datetime CreatedAt;

			%read-only csv_string AvailableRoles {
				default "";
			}

			bool SetRunLevel(%in %strict int32 RequestedRunLevel);
			bool Restart(%in %strict string RestartReason);

			/***
			* Modify the constraints of the EE. The changes will be applied after a Restart of the EE.
			*/
			bool ModifyConstraints(%in bool Force, %in int64 AllocatedDiskSpace, %in int64 AllocatedMemory, %in int32 AllocatedCPUPercent);

			/***
			* Modify the list of roles which may be assigned to any DeploymentUnit installed into this ExecEnv
			*/
			bool ModifyAvailableRoles(%in csv_string AvailableRoles = "");

			/***
			* Delete the execution environment
			*/
			bool Delete();
		}

		/***
		 * https://usp-data-models.broadband-forum.org/tr-181-2-14-0-usp.html#D.Device:2.Device.SoftwareModules.DeploymentUnit.{i}.
		 *
		 */
		%read-only object DeploymentUnit[] {
			counted with DeploymentUnitNumberOfEntries;

			%key string UUID {
			/**
				on action validate call check_maximum_length 36;
			*/
			}
			%read-only string DUID {
				default "000000000000000000000000000000000000";
				on action validate call check_maximum_length 36;
			}
			%unique %key string Alias {
				on action validate call check_maximum_length 64;
			}
			%read-only string Name {
				on action validate call check_maximum_length 64;
			}
			%read-only string Status {
				default "Installing";
				on action validate call check_enum [ "Installing", "Installed", "Updating", "Uninstalling", "Uninstalled", "Failed" ];
			}
			%read-only bool Resolved {
				default true;
			}
			%read-only string URL {
				on action validate call check_maximum_length 2048;
			}
			%read-only string Description {
				default "";
				on action validate call check_maximum_length 256;
			}
			%read-only string Vendor {
				on action validate call check_maximum_length 128;
			}
			%read-only string Version {
				on action validate call check_maximum_length 32;
			}
			%read-only csv_string VendorLogList {
				default "";
			}
			%read-only csv_string VendorConfigList{
				default "";
			}
			%read-only csv_string ExecutionUnitList{
				default "";
			}
			%read-only datetime Installed;
			%read-only datetime LastUpdate;
			%key string ExecutionEnvRef;
                        %read-only string ModuleVersion {
                                on action validate call check_maximum_length 32;
                        }


			%async bool Update(%in %strict string URL,
			 			%in %strict string Username,
						%in %strict string Password,
						%in bool RetainData,
						%in int32 AllocatedMemory,
						%in int32 AllocatedDiskSpace,
						%in int32 AllocatedCPUPercent,
						%in list HostObject,
						%in list NetworkConfig,
						%in list EnvVariable,
                                                %in string ModuleVersion,
						%in %strict htable Data,
						%in csv_string RequiredRoles,
						%in csv_string OptionalRoles);

			%async bool Uninstall(%in bool RetainData);
		}

		/***
		 *
		 *
		 */
		%read-only object ExecutionUnit[] {
			counted with ExecutionUnitNumberOfEntries;

			%key string EUID {
			/**
				on action validate call check_maximum_length 64;
			*/
			}
			%unique %key string Alias {
				on action validate call check_maximum_length 64;
			}
			%read-only string Name {
				on action validate call check_maximum_length 32;
			}
			%read-only string ExecEnvLabel {
				on action validate call check_maximum_length 64;
			}
			%read-only string Status {
                default "Idle";
                on action validate call check_enum [ "Idle",
                    "Starting", "Active", "Stopping", "Restarting"];
            }
			%read-only string ExecutionFaultCode {
				default "NoFault";
				on action validate call check_enum [ "NoFault", "FailureOnStart", "FailureOnAutoStart", "FailureOnStop", "FailureWhileActive", "DependencyFailure", "UnStartable" ];
			}
			%read-only string ExecutionFaultMessage {
				on action validate call check_maximum_length 256;
			}
			bool AutoStart;

			uint16 RunLevel;
			%read-only string Vendor {
				on action validate call check_maximum_length 128;
			}
			%read-only string Version {
				on action validate call check_maximum_length 32;
			}
			%read-only string Description {
				on action validate call check_maximum_length 256;
			}

			%read-only int32 AllocatedDiskSpace {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call eu_read_stats;
			}
			%read-only int32 AllocatedMemory {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call eu_read_stats;
			}
			%read-only int32 AllocatedCPUPercent {
				default -1;
				on action validate call check_range { min = -1, max = 100 };
				on action read call eu_read_stats;
			}

			%read-only int32 AvailableDiskSpace {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call eu_read_stats;
			}
			%read-only int32 AvailableMemory {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call eu_read_stats;
			}

			%read-only int32 DiskSpaceInUse {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call eu_read_stats;
			}
			%read-only int32 MemoryInUse {
				default -1;
				on action validate call check_range { min = -1, max = 2147483647 };
				on action read call eu_read_stats;
			}

			%read-only csv_string References;
			%read-only csv_string AssociatedProcessList;
			%read-only csv_string VendorLogList;
			%read-only csv_string VendorConfigList;
			%read-only string ExecutionEnvRef;

			%read-only object NetworkConfig {
				%read-only object AccessInterfaces[] {
					%read-only string Reference;
				}
				%read-only object PortForwarding[] {
					%read-only string Interface;
					%read-only uint32 ExternalPort;
					%read-only uint32 InternalPort;
					%read-only string Protocol;
				}
				%read-only csv_string X_PRPL-COM_DNSSDRefList;
			}

			%read-only object HostObject[] {
				%unique %key string Alias {
					on action validate call check_maximum_length 64;
				}
				%read-only string Source {
					on action validate call check_maximum_length 256;
				}
				%read-only string Destination {
					on action validate call check_maximum_length 256;
				}
				%read-only string Options {
					on action validate call check_maximum_length 256;
				}
			}
			%read-only object EnvVariable[] {
				%read-only string Key {
					on action validate call check_maximum_length 256;
				}
				%read-only string Value {
					on action validate call check_maximum_length 256;
				}
				%unique %key string Alias {
					on action validate call check_maximum_length 64;
				}
			}

			bool SetRequestedState(%in %strict string RequestedState);
			bool ModifyNetworkConfig(%in list NetworkConfig);
			object Extensions {
				// To Define
			}
		}

		%read-only object NetworkConfig {
			%read-only object Interfaces[] {
				/** The logical name of the interface */
				%read-only string Name;
				/** A reference to a Device.Logical.Interfaces.{i}. row */
				%read-only string Reference;
			}
			/** the bridge to which the containers will connect */
			%read-only string DefaultBridge;
			/** row in Firewall.Chain. to which the firewall rules should be applied */
			%read-only string DefaultFirewallChain;
		}
	}
}

%populate {
    on event "dm:object-changed" call eu_change_autostart
		filter 'path matches "^SoftwareModules\.ExecutionUnit\.[0-9]+\.$" && contains("parameters.AutoStart")';

	on event "dm:object-changed" call ee_change_enable
		filter 'path matches "^SoftwareModules\.ExecEnv\.[0-9]+\.$" && contains("parameters.Enable")';
}

