    // bus specific configuration
    pcb = {
        register-name = "${name}"
    };

    privileges = {
        keep-all = true
    };

    sahtrace = {
        type = "file",
	    file = "/logs/cthulhu.log",
        level = 500
    };

    trace-zones = {cthulhu_main = 500,
                   cthulhu_dm = 500,
                   cthulhu_events = 500,
                   cthulhu_lxc = 500,
                   cthulhu_archive = 500,
                   cthulhu_autorestart = 500,
                   cthulhu_sb = 500,
                   cthulhu_ns = 500,
                   cthulhu_helpers = 500,
                   cthulhu_ovl = 500,
                   cthulhu_storage = 500,
                   cthulhu_cgroup = 500,
                   cthulhu_rpc = 500,
                   cthulhu_syslogng = 500,
                   cthulhu_annotations = 500,
                   cthulhu_plugins = 500,
                   cthulhu_onboard = 500,
                   rpc = 500,
                   plugin = 500};

    // Application specific settings

    // persistent storage location
    // rw_data_path = "/etc/config";
    storage-path = "${rw_data_path}/${name}/";

    // main files
    definition_file = "${name}_definition.odl";
    config_file = "${name}_config.odl";

    odl = {
        load-dm-events = true,
        dm-load = true,
        dm-defaults = "defaults.d/",
        dm-save = true,
        dm-save-on-changed = true,
        dm-save-delay = 1000,
        directory = "${storage-path}/odl"
    };
}

import "${name}.so" as "${name}";

include "${definition_file}";
include "${config_file}";

#include "mod_sahtrace.odl";

%define {
    entry-point cthulhu.cthulhu_main;
}

etc/amx/cthulhu/cthulhu_config.odl.text:
%populate {
    object 'Cthulhu' {
        object 'Config' {
            parameter 'DefaultBackend' = "/usr/lib/cthulhu-lxc/cthulhu-lxc.so";
            parameter 'ImageLocation' = "/opt/lcm/usr/share/rlyeh/images";
            parameter 'BlobLocation' = "/opt/lcm/usr/share/rlyeh/blobs";
            parameter 'BundleLocation' = "/opt/lcm/usr/share/celephais/bundles";
            parameter 'StorageLocation' = "/opt/lcm/usr/share/cthulhu";
            parameter 'PluginLocation' = "/usr/lib/amx/cthulhu/plugins";
            parameter 'UseOverlayFS' = true;
            parameter 'OnboardingFile' = "/opt/lcm/usr/share/cthulhu/cthulhu_onboarded";
            parameter 'OnboardingLocation' = "/etc/amx/cthulhu/onboard";
        }
    }
}

etc/amx/cthulhu/cthulhu_definition.odl.text:
%define {
    /*
     *  Cthulhu data model
     *  Cthulhu is responsible for creating, starting and stopping of containers.
     *  Constraints of (sets of) containers are controlled by Sandboxes
    */
    %persistent object Cthulhu {

        event "cthulhu:error";

        event "cthulhu:ctr:created";
        event "cthulhu:ctr:updated";
        event "cthulhu:ctr:removed";
        event "cthulhu:ctr:running";
        event "cthulhu:ctr:paused";
        event "cthulhu:ctr:stopped";
        event "cthulhu:ctr:list";
        event "cthulhu:ctr:ps";
        event "cthulhu:ctr:state";
        event "cthulhu:sb:created";
        event "cthulhu:sb:updated";
        event "cthulhu:sb:removed";
        event "cthulhu:sb:list";
        event "cthulhu:sb:running";
        event "cthulhu:sb:paused";
        event "cthulhu:sb:stopped";
        event "cthulhu:sb:state";
        event "cthulhu:initialized";
        event "cthulhu:backend:changed";

        /**
         * Load a backend
         * %param string full path of the plugin
         */
        bool loadBackend(%in %mandatory %strict string Backend);

        /**
         * Section that contains global configuration options for Cthulhu
         */
        %persistent object Config {
            /**
             * this backend will be loaded by default
             */
            %read-only string DefaultBackend;
            /**
            * Configure whether Cthulhu will use overlayFS to create the rootFS of a container and for persistent
            * data of te container.
            * If this setting is changed, then Cthulhu should be restarted and all the containers have to be reinstalled.
            */
            %read-only bool UseOverlayFS = true;
            /**
            * The image specs of the containers should be located in this directory
            */
            %read-only string ImageLocation;
            /**
             * The downloaded layers should be located in this directory
             */
            %read-only string BlobLocation;
            /**
            * Configure whether Cthulhu will use bundles
            */
            %read-only bool UseBundles = false;
            /**
            * OCI runtime bundle archives should be located in this directory
            */
            %read-only string BundleLocation;
            /**
             * Cthulhu will store all the containers here
             */
            %read-only string StorageLocation;
            /**
             * The location where Cthulhu will look for plugins
             */
            %read-only string PluginLocation;
            /**
             * Location of file that indicates onboarding has happened
             * its a firstboot mechanism
             */
            %read-only string OnboardingFile;
            /**
             * Location of the directory containing the json files for onboarding a container
             */
            %read-only string OnboardingLocation;
        }

        /**
         * Section that contains global information about Cthulhu
         */
        %persistent object Information {
            /**
             * git version of this component
             */
            %read-only string Version;
            %read-only string BackendName;
            /**
              * version of the backend, if loaded
             */
            %read-only string BackendVersion;
            %read-only bool BundlesSupported = false;
            %read-only bool OverlayFSOnCreate = false;
            /**
             * Internal setting to know when the defaults are loaded
             */
            %read-only %persistent bool odlLoaded = false;
            /**
             * Will be set to true when initialization has finished
             */
            %read-only bool Initialized = false;
        }

        /**
         * Plugins can add global settings to the datamodel at this location
         */
        %persistent object Plugins {}
        /**
         * Plugins can add global settings to the datamodel at this location
         * settings in here will not be shown in SoftwareModules
         */
        %persistent object PluginsPrivate {}

        /**
         * Section that allows to control containers.
         * All containers are also listed under this section.
         */
        %persistent object Container {
            /**
             * Generic command entry that will call other functions
             *
             * @param Command The Command to execute. E.g. create, start, stop
             * @param CommandID optional identifier of this command, to link the events with the command
             * @param Parameters The parameters that the command need
             */
            void command(%in %mandatory %strict string Command,
                         %in %strict string CommandID,
                         %in %strict htable Parameters);

            /**
             * Creates a container with id ContainerId, using the image located at Bundle
             *
             * If the ContainerId matches that of any existing container on the CPE
             * (including those in a 'paused' or 'stopped' state), Cthulhu will
             * immediately publish a "created" notification and will take no further action.
             * Otherwise Cthulhu will attempt to create the container and either
             * a "created" notification or an error will result.
             *
             * @param ContainerId Unique identifier of this instance
             * @param UUID The uuid of the deployment unit linked to the container
             * @param Bundle The name of the image in Rlyeh that should be installed
             * @param BundleVersion The version of the image in Rlyeh that should be installed. If empty, then tag "latest" will be installed
             * @param DiskLocation If the image is installed in a hiererarchy, this parameter gives a location where Cthulhu should look for the image
             *                     e.g. if the image is installed from https://repo.domain.com/best_images/release/smart_image, then this parameter should be "best_images/release/smart_image"
             * @param Sandbox Define in which Sandbox the Container should be installed
             * @param Autostart Defines whether the container should autmatically start after creation or on restart of the service
             * @param AutoRestart Defines whether the Automatically restart of the container on failure should be activated
             * @param AllocatedCPUPercent Limit the CPU usage of this container. valid range from 0 to 100. -1 = unlimited
             * @param AllocatedMemory Limit the Memory usage of this container. Values are in Kb. -1 = unlimited
             * @param AllocatedDiskSpace Limit the Disk Space usage of this container. Values are in Kb. -1 = limitation is defined by the Sandbox
             * @param HostObject A list of host objects that should be shared from the host to the container. If HostObject argument is present, then all existing HostObjects will be removed before applying the new list.
                                 there are two types of hostobjects: mounts and devices. The type should be provided in the options.If a device is added: following options need to be present:
                                    * type=device
                                    * devicetype
                                    * major
                                    * minor
                                    * access
                                    * create
                                 Example: HostObject = [{ "Source" = "/dir_on_host", "Destination" = "dir_on_ctr", Options = "type=mount"},
                                  { "Source" = "/var/data", "Destination" = "/var/data", Options = "type=mount,default,bind,noexec,ro"},
                                  { "Source"= "", "Destination"= "/dev/tty60", Options  = "type=device,devicetype=c,major=4,minor=60,access=rwm,create=1"}]
                                 If Source = "tmpfs" then a tmpfs will be created on the destination.
             * @param NetworkConfig Network configuration
             * @param ModuleVersion The version of as set by the caller (controller) combining the image version and all the provided parameter set
             * @param Data Allows to configure plugins if installed
             */
            void create(%in %mandatory %strict string ContainerId,
                        %in %mandatory %strict string Bundle,
                        %in %strict string LinkedUUID,
                        %in %strict string BundleVersion,
                        %in %strict string DiskLocation,
                        %in %strict string Sandbox = "generic",
                        %in bool Autostart,
                        %in bool AutoRestart,
                        %in int32 AllocatedCPUPercent,
                        %in int32 AllocatedMemory,
                        %in int32 AllocatedDiskSpace,
                        %in list HostObject,
                        %in list NetworkConfig,
                        %in %strict string ModuleVersion,
                        %in %strict htable Data);

            /**
             * Updates a container to a new version
             *
             * @param ContainerId the container to update
             * @param Bundle this bundle will be used. If not provided, the bundle name form the existing container will be used
             * @param BundleVersion the new version to update to. If not provided, then the container will be updated to 'latest'
             * @param RemoveData Lets the user choose if the data should be retained or removed in
             between updates
             *
             * @param ContainerId Unique identifier of the instance
             * @param Bundle The name of the image in Rlyeh that should be installed
             * @param BundleVersiob The version of the image in Rlyeh that should be installed. If empty, then tag "latest" will be installed
             * @param DiskLocation If the image is installed in a hiererarchy, this parameter gives a location where Cthulhu should look for the image
             *                     e.g. if the image is installed form https://repo.domain.com/best_images/release/smart_image, then this parameter should be "best_images/release/smart_image"
             * @param RemoveData Remove the Data of the old container before updating, or not
             * @param AllocatedCPUPercent Limit the CPU usage of this container. valid range from 0 to 100. -1 = unlimited. If not provided, the previous value will be kept
             * @param AllocatedMemory Limit the Memory usage of this container. Values are in Kb. -1 = unlimited. If not provided, the previous value will be kept
             * @param AllocatedDiskSpace Limit the Disk Space usage of this container. Values are in Kb. -1 = limitation is defined by the Sandbox. If not provided, the previous value will be kept
             * @param HostObject A list of host objects that should be shared from the host to the container. Currently, only files, directories and tmpfs are
             *                   supported. If HostObject argument is present, then all existing HostObjects will be removed before applying the new list.
                                 Example: HostObject = [{ "Source" = "/dir_on_host", "Destination" = "dir_on_ctr", Options = "<mount options>"}, { "Source" = "/var/data", "Destination" = "/var/data", Options = "default,bind,noexec,ro"}]
                                 If Source = "tmpfs" then a tmpfs will be created on the destination.
             * @param ModuleVersion The version of as set by the caller (controller) combining the image version and all the provided parameter set
             * @param NetworkConfig Network configuration
             */
            void update(%in %mandatory %strict string ContainerId,
                        %in %mandatory %strict string Bundle,
                        %in %mandatory %strict string BundleVersion,
                        %in %strict string DiskLocation,
                        %in bool RemoveData = false,
                        %in int32 AllocatedCPUPercent,
                        %in int32 AllocatedMemory,
                        %in int32 AllocatedDiskSpace,
                        %in list HostObject,
                        %in list NetworkConfig,
                        %in %strict string ModuleVersion);


            /**
             * Starts (enables) the container with id ContainerId
             *
             * @param ContainerId Unique identifier of the instance
             */
            void start(%in %mandatory %strict string ContainerId);
            /**
             * Stops (disables) the container with id ContainerId
             *
             * @param ContainerId Unique identifier of the instance
             */
            void stop(%in %mandatory %strict string ContainerId);
            /**
             * Restarts the container with id ContainerId
             *
             * @param ContainerId Unique identifier of the instance
             */
            void restart(%in %mandatory %strict string ContainerId);
            /**
             * Removes the container with id ContainerId
             *
             * @param ContainerId Unique identifier of the instance
             * @param RemoveData Removes the persistent data on deletion. If false, the container will be present in the data model as "Ghost"
             */
            void remove(%in %mandatory %strict string ContainerId,
                        %in bool RemoveData = true);
            /**
             * Requests a list of the defined containers.
             * The result is returned in a "list" notification.
             *  The "quiet" property is optional. If it is present and has the value true then
             *  the resulting notification will contain only the containerIDs, otherwise it
             *  will also contain the PID, status, and bundle path of each container.
             */
            void ls(%in bool quiet);

            /**
             * Modify the resource constraints of the container
             *
             * The constraints will only be taken into account after a restart of the container
             *
             * @param ContainerId The container to be modified
             * @param Force Determines the behaviour if a request is made which would reduce the allocation of a resource below the amount which is currently being used.
             * @param AllocatedCPUPercent Limit the CPU usage of this container. valid range from 0 to 100. -1 = unlimited
             * @param AllocatedMemory Limit the Memory usage of this container. Values are in Kb. -1 = unlimited
             * @param AllocatedDiskSpace Limit the Disk Space usage of this container. Values are in Kb. -1 = limitation is defined by the Sandbox
             */
            void modify(%in %mandatory %strict string ContainerId,
                        %in bool Force,
                        %in int32 AllocatedCPUPercent,
                        %in int32 AllocatedMemory,
                        %in int32 AllocatedDiskSpace);

            void modifyNetworkConfig(%in %mandatory %strict string ContainerId,
                                     %in list NetworkConfig);

            /**
             * A list of all currently installed containers
             */
            %persistent %read-only object Instances[] {
                /** Alias of the instance */
                %unique %key string Alias;
                /** Unique ID of the container */
                %persistent %read-only string ContainerId;
                /** Status of the container */
                %read-only string Status {
                    default "Ghost";
                    on action validate call check_enum [ "Ghost",
                        "Unknown", "Created",
                        "Stopped", "Starting", "Running", "Stopping", "Restarting",
                        "Aborting", "Freezing", "Frozen", "Thawed"];
                }
                /** Image on which the container is based */
                %persistent %read-only string Bundle;
                /** Version of the image installed */
                %persistent %read-only string BundleVersion;
                /** Vendor of the image */
                %persistent %read-only string Vendor;
                /** Description of the image, provided by the vendor */
                %persistent %read-only string Description;
                /** Automatically start this container if its containing Sandbox starts */
                %persistent bool Autostart = true;
                /** Sandbox in which the container is installed */
                %persistent %read-only string Sandbox;
                /** reference to the private sandbox of the container. For internal purposes only. */
                %persistent %read-only string PrivateSandbox;
                /** Timestamp when the container was created */
                %persistent %read-only datetime Created;
                /** Timestamp when the container was last updated */
                %persistent %read-only datetime Updated;
                /** Owner of the container. */
                %persistent %read-only string Owner;
                /** PID of the container process when running. -1 if the container is not active */
                %read-only int32 Pid = -1;
                /** UUID linked to the container --> reference to the deploymentunit */
                %persistent %read-only string LinkedUUID;
                /** reference to all installed layers that compose the rootfs */
                %persistent %read-only object Layers[] {
                    /** index of the layer. Layers are mounted from low to high index */
                    %persistent %read-only uint32 Index;
                    /** name of the layer, as present on disk */
                    %persistent %read-only string Layer;
                }
                /** Version of the image installed and all its parameter*/
                %persistent %read-only string ModuleVersion;
                /** Parameters relevant to the AutoRestart feature */
                %persistent object AutoRestart {
                    /**
                     * If enabled, the container will restart after it is detected that is stopped running
                     */
                    %persistent bool Enabled = false;
                    /**
                     * Number of times the container failed to start. This will be reset when the container
                     * runs successfully for 60 minutes.
                     */
                    uint32 RetryCount;
                    /**
                     * Indicates since when the container is running.
                     */
                    datetime RunningSince;
                    /**
                     * Indicates when the last retry attempt was done.
                     */
                    datetime LastRetry;
                    /**
                     * Indicates when a new attempt will be done to restart the container if a failure is detected.
                     */
                    datetime NextRetry;
                }
                /** defines which files or directories should be bind mounted in from the host in the container
                 *
                 * If the file or directory does not exist in the container file system, it will be created
                 */
                %persistent object Mounts[] {
                    /** Location on the host of the file or directory */
                    %persistent string Source;
                    /** Location in the container where to mount the file or directory */
                    %persistent string Destination;
                    /** Type if filesystem (see mount). This allows for intance to create tmpfs in the container */
                    %persistent string Type;
                    /** extra options for te mount command. These can be different depending on the Type */
                    %persistent string Options;
                }
                /** HostObjects defined by SoftwareModules through InstallDU or Update
                 * these are internally stored under Mounts and Devices, but this copy is kept
                 * to represent the HostObjects to SoftwareModules. Changes to this data will not reflect
                 * in the Containers!!!
                */
                %persistent %read-only object HostObject[] {
                    /** Location on the host of the file or directory */
                    %persistent %read-only string Source;
                    /** Location in the container where to mount the file or directory */
                    %persistent %read-only string Destination;
                    /** extra options for te mount command. These can be different depending on the Type */
                    %persistent %read-only string Options;
                }
                /** Resource statistics and restrictions of the container */
                object Resources {
                    /** Allocated diskspace, in Kb. This should be minimum 1024 */
                    int32 AllocatedDiskSpace {
                        on action read call ctr_resource_read;
                        on action write call ctr_resource_write;
                    }
                    /** Allocated CPU in percent */
                    int32 AllocatedCPUPercent {
                        on action read call ctr_resource_read;
                        on action write call ctr_resource_write;
                    }
                    /** Allocated momory, in Kb */
                    int32 AllocatedMemory {
                        on action read call ctr_resource_read;
                        on action write call ctr_resource_write;
                    }
                    /** Statistics */
                    %read-only object Stats {
                        /** Diskspace statistics in Kb */
                        %read-only object DiskSpace {
                            on action read call ctr_stats_read;
                            /** Total available diskspace */
                            %read-only int64 Total;
                            /** Diskspace used */
                            %read-only int64 Used;
                            /** Diskspace still available */
                            %read-only int64 Free;
                        }
                        /** Memory statistics in Kb */
                        %read-only object Memory {
                            on action read call ctr_stats_read;
                            /** Total memory available */
                            %read-only int64 Total;
                            /** Memory used */
                            %read-only int64 Used;
                            /** Memory still available */
                            %read-only int64 Free;
                        }
                    }
                }
                /** network interfaces active in a running container */
                %read-only object Interfaces[] {
                    /** The interface name */
                    %read-only string Name;
                    /** a list of IP addresses that are assigned to this interface */
                    %read-only object Addresses[] {
                        /** an IP address */
                        %read-only string Address;
                    }
                }
                /** Plugins can add settings, specific for a container, to the datamodel at this location */
                %persistent object Plugins {}
                /**
                * Plugins can add global settings to the datamodel at this location
                * settings in here will not be shown in SoftwareModules
                */
                %persistent object PluginsPrivate {}
            } // Container instances
        } // Container

        /**
         * Section that allows to control sandboxes.
         * All sandboxes are also listed under this section.
         */
        %persistent object Sandbox {
            /**
             * Generic command entry that will call other functions
             *
             * @param Command The Command to execute. E.g. create, start, stop
             * @param CommandID optional identifier of this command, to link the events with the command
             * @param Parameters The parameters that the command need
             */
          void command(%in %mandatory %strict string Command,
                       %in %strict string CommandID,
                       %in %strict htable Parameters);

          /**
           * Create an execution environment
           * optional parameters:
           * @param Parent SandboxId
           * @param Enable automatocally enable the sandbox after creation and on reboot
           * @param Version The version of the sandbox
           * @param Vendor The vendor of the sandbox
           * @param AllocatedCPUPercent percent of the total cpu load that the sandbox is allowed to consume
           * @param AllocatedMemory amount of memory in kilobytes that the sandbox is allowed to allocate
           * @param AllocatedDiskSpace diskspace in kilobytes that will be preallocated for this sandbox.  This should be minimum 1024.
           */
          void create(%in %mandatory %strict string SandboxId,
                 %in string Parent,
                 %in bool Enable = true,
                 %in string Version,
                 %in string Vendor,
                 %in int32 AllocatedCPUPercent,
                 %in int32 AllocatedMemory,
                 %in int32 AllocatedDiskSpace);

         /**
          * Modify the resource constraints of the sandbox
          *
          * The constraints will only be taken into account after a restart of the container
          *
          * @param SandboxId the sandbox to be modified
          * @param Force Determines the behaviour if a request is made which would reduce the allocation of a resource below the amount which is currently being used.
          * @param AllocatedCPUPercent Limit the CPU usage of this container. valid range from 0 to 100. -1 = unlimited
          * @param AllocatedMemory Limit the Memory usage of this container. Values are in Kb. -1 = unlimited
          * @param AllocatedDiskSpace Limit the Disk Space usage of this container. Values are in Kb. -1 = limitation is defined by the Sandbox
          */
          void modify(%in %mandatory %strict string SandboxId,
                 %in bool Force,
                 %in int32 AllocatedCPUPercent,
                 %in int32 AllocatedMemory,
                 %in int32 AllocatedDiskSpace);
          /**
            * Remove a sandbox
            *
            * @param SandboxId the sandbox identifier
            */
          void remove(%in %mandatory %strict string SandboxId);
          /**
            * Start a sandbox
            *
            * @param SandboxId the sandbox identifier
            */
          void start(%in %mandatory %strict string SandboxId);
          /**
            * Stop a sandbox
            *
            * @param SandboxId the sandbox identifier
            */
          void stop(%in %mandatory %strict string SandboxId);
          /**
            * Restart a sandbox
            *
            * @param SandboxId the sandbox identifier
            * @param Reason optional reason that will be put in the restart event
            */
          void restart(%in %mandatory %strict string SandboxId, %in %strict string RestartReason);

          /**
            * Execute a command in the namespace of the sandbox. For testing purposes only.
            *
            * @param SandboxId the sandbox identifier
            * @param Cmd The command ot execute
            */
          void exec(%in %mandatory %strict string SandboxId,
                %in %mandatory %strict string Cmd);

          /**
            * List all sandboxes.
            *
            * The result will be returned as an event
            */
          void ls(%in bool Quiet);

            /**
             * A list of all sandboxes
             */
              %persistent %read-only object Instances[] {
              /** Alias of the instance */
              %unique %key string Alias;
              /** Unique ID of the sandbox */
              %persistent string SandboxId;
              /** The version of the sandbox */
              %persistent string Version;
              /** the vendor of the sandbox */
              %persistent string Vendor;
              /** Indicates whether the sandbox is created by a container (private container) to allow managing resources on a per-container basis. For internal use only */
              %persistent %read-only bool CreatedByContainer = false;
              /** Last reason for restarting the sandbox */
              %persistent string RestartReason;
              /** Parent of a nested sandbox */
              %persistent string Parent;
              /** Enable or disable the sandbox */
              %persistent bool Enable;
              /** Timestamp when sandbox was created */
              %persistent %read-only datetime Created;
              /** decription of the sandbox */
              %persistent string Description;
              /** status of the sandbox */
              %read-only string Status {
                  default "Disabled";
                  on action validate call check_enum [
                      "Up", "Restarting", "Disabled"];
              }
              /** Pid of the sandbox process, when it is enabled */
              int32 Pid = -1;
              /** Allocated diskspace, in Kb. This should be minimum 1024 */
              %persistent int32 AllocatedDiskSpace = 1024;
              /** Allocated CPU in percent */
              %persistent int32 AllocatedCPUPercent = 100;
              /** Allocated momory, in Kb */
              %persistent int32 AllocatedMemory = -1;
              /** a list or devices that are allowed or denied. */
              %persistent object Devices[] {
                  /** the path of the device */
                  %persistent string Device = "";
                  /** allow or deny the device */
                  %persistent string Permission {
                  default "Allow";
                  on action validate call check_enum [
                      "Allow", "Deny"];
                  }
                  /** type of the device: character or block or all (wildcard) */
                  %persistent string Type {
                    default "c";
                    on action validate call check_enum [
                      "a", "c", "b"];
                  }
                  /** device major number, -1 == wildcard */
                  %persistent int32 Major = 0;
                  /** device minor number, -1 == wildcard */
                  %persistent int32 Minor = 0;
                  /** access of the device" read, write, mknod */
                  %persistent string Access {
                    default "rwm";
                    on action validate call check_enum [
                      "r", "rm", "w", "wm", "rw", "rwm"];
                  }
                  /** defines whether device will be created if it does not exist in the container */
                  %persistent bool Create = False;
              }
              /** UTS namespace */
              %persistent object UtsNS {
                  /** Enable or disable the UTS namespace */
                  %persistent bool Enable = False;
                  /** histname of the UTS namespace */
                  %persistent string Hostname;
              }
/** Not implemented yet
              %persistent object UserNS {
                  %persistent bool Enable;
                  %persistent object Mappings[] {
                      %persistent string Mapping;
                  }
              }
*/
              /** Network namespace */
              %persistent object NetworkNS {
                  /**Enable or disable the network namespace */
                  %persistent bool Enable;
                  /** Type of noetwork namespace
                    * Empty: an empty network namespace is created. There will be no network connection
                    * ParentSandbox: Use the network namespace of the parent, if this is a nested sandbox
                    * Veth: use virtuel ethernet devices to connect the network namespace with other network namespaces
                    */
                  %persistent string Type {
                      default "Empty";
                      on action validate call check_enum [
                          "Empty", "ParentSandbox", "Veth"];
                  }
                  /** Network interfaces which will be created in case of Veth */
                  %persistent object Interfaces[] {
                      /** Name of the veth interface in the container */
                      %persistent string Interface {
                          default "eth0";
                      }
                      /** bridge in the host namespace to which the veth interface should be added */
                      %persistent string Bridge;
                  }
              }
/** Not implemented yet
              %persistent object MountNS {
                  %persistent bool Enable;
                  %persistent object Mounts[] {
                      %persistent string Host;
                      %persistent string Target;
                  }
              }
*/
              /** Statistics */
              %read-only object Stats {
                  /** Diskspace statistics in Kb */
                  %read-only object DiskSpace {
                      on action read call sb_stats_read;
                      /** Total available diskspace */
                      %read-only int64 Total;
                      /** Diskspace used */
                      %read-only int64 Used;
                      /** Diskspace still available */
                      %read-only int64 Free;
                  }
                  /** Memory statistics in Kb */
                  %read-only object Memory {
                      on action read call sb_stats_read;
                      /** Total memory available */
                      %read-only int64 Total;
                      /** Memory used */
                      %read-only int64 Used;
                      /** Memory still available */
                      %read-only int64 Free;
                  }
              }
            /** Plugins can add settings, specific for a sandbox, the datamodel at this location */
            %persistent object Plugins {}
            /**
            * Plugins can add global settings to the datamodel at this location
            * settings in here will not be shown in SoftwareModules
            */
            %persistent object PluginsPrivate {}

          } // Sandbox instances
        } // Sandbox
    } // Cthulhu
}

%populate {
    on event "dm:object-changed" call container_updated
      filter 'path in search_path("Cthulhu.Container.Instances.*.")';

    on event "dm:object-changed" call sandbox_updated
      filter 'path in search_path("Cthulhu.Sandbox.Instances.*.")';

    on event "dm:object-changed" call container_autorestart_enabled
      filter 'path in search_path("Cthulhu.Container.Instances.*.AutoRestart.") &&
              parameters.Enabled.to == true';

    on event "dm:object-changed" call odl_loaded
      filter 'path in search_path("Cthulhu.Information.") &&
              parameters.odlLoaded.to == true';

    // on event "*" call print_event;

}

