etc/amx/rlyeh/rlyeh_definition.odl.text:
%define {
    object Rlyeh {

        event "rlyeh:image:list";
        event "rlyeh:image:status";
        event "rlyeh:image:pulled";
        event "rlyeh:image:markedremove";
        event "rlyeh:image:removed";
        event "rlyeh:error";

        /*
